import * as React from "react"
import { getDialogProps } from "../editable/dialog-props"
import ImageSpread from "./image-spread"
import ImageBleed from "./image-bleed"
import { cnPage } from "../ui/cn"
import { useImageLoadFailure } from "./use-image-load-failure"
import {
  renderOverlay,
  renderOptionsButton,
  useShouldShowOptions,
} from './image-overlay-utils'

type OptionSelectEvent = Event | React.SyntheticEvent

export type ImageOption = {
  id: string
  label: string
  icon?: React.ReactNode
  dialog?: Record<string, any> | null
  onSelect?: (event: OptionSelectEvent) => void
  disabled?: boolean
}

type ImageRenderProps = React.ImgHTMLAttributes<HTMLImageElement>

interface ImageWithOptionsProps {
  src?: string
  alt?: string
  onError?: React.ReactEventHandler<HTMLImageElement>
  className?: string
  imageClassName?: string
  style?: React.CSSProperties
  imageStyle?: React.CSSProperties
  overlaySvg?: string
  overlayClassName?: string
  options?: ImageOption[]
  dialog?: Record<string, any> | null
  dialogProps?: Record<string, any>
  placeholder?: React.ReactNode
  children?: React.ReactNode
  imageProps?: React.ImgHTMLAttributes<HTMLImageElement>
  renderImage?: (props: ImageRenderProps) => React.ReactNode
}

const ImageWithOptions = ({
  src,
  alt = "",
  className,
  imageClassName,
  style,
  imageStyle,
  overlaySvg,
  overlayClassName,
  options = [],
  dialog,
  dialogProps,
  placeholder,
  children,
  imageProps,
  renderImage,
  onError,
}: ImageWithOptionsProps) => {
  const baseDialogProps = React.useMemo(() => (dialog ? getDialogProps({ dialog }) : {}), [dialog])
  const showOptions = useShouldShowOptions(options)
  const imageLoadErrorHandler = useImageLoadFailure({
    onError: (event) => {
      onError?.(event)
      imageProps?.onError?.(event)
    },
  })

  const mergedDialogProps = React.useMemo(() => {
    if (!dialogProps) return baseDialogProps
    const merged: Record<string, any> = { ...baseDialogProps, ...dialogProps }
    if (baseDialogProps.className || dialogProps.className) {
      merged.className = cnPage(baseDialogProps.className, dialogProps.className)
    }
    Object.keys(baseDialogProps).forEach((key) => {
      const baseHandler = baseDialogProps[key]
      const extraHandler = dialogProps[key]
      if (key.startsWith("on") && typeof baseHandler === "function" && typeof extraHandler === "function") {
        merged[key] = (event: any) => {
          baseHandler(event)
          extraHandler(event)
        }
      }
    })
    return merged
  }, [baseDialogProps, dialogProps])

  const resolvedSrc = imageProps?.src ?? src

  // Nothing to draw and nothing supplied to stand in for it. Mark the node so a template
  // can render an empty-state placeholder: without a marker this is an invisible
  // full-size region whose only affordance is the indicator dot, which reads as a blank
  // page rather than an image waiting to be filled.
  const isEmptyImage = !resolvedSrc && !placeholder && !renderImage

  const renderImageContent = () => {
    const imagePropsClassName = imageProps?.className
    const imagePropsStyle = imageProps?.style
    const finalSrc = resolvedSrc
    const finalAlt = imageProps?.alt ?? alt
    const mergedImageProps: React.ImgHTMLAttributes<HTMLImageElement> = {
      ...imageProps,
      src: finalSrc,
      alt: finalAlt,
      className: cnPage("uhuu-image-img", imageClassName, imagePropsClassName),
      style: { ...imageStyle, ...imagePropsStyle },
    }

    if (renderImage) {
      return renderImage(mergedImageProps)
    }

    if (finalSrc) {
      return <img {...mergedImageProps} onError={imageLoadErrorHandler} />
    }

    return placeholder ?? null
  }

  const hasDataUhuu = mergedDialogProps['data-uhuu'];

  // Check if the children contains ImageSpread or ImageBleed    
  const hasImageSpreadOrBleed = React.Children.toArray(children).some((child: any) => {
    if (!React.isValidElement(child)) return false;
    return (child.type === ImageSpread || child.type === ImageBleed);
  });

  // Move the binding marker onto the positioned image without mutating the memoized props.
  const bodyDialogProps = { ...mergedDialogProps };
  if (hasImageSpreadOrBleed) delete bodyDialogProps['data-uhuu'];

  // Pass the data-uhuu prop to the children
  const childrenWithProps = React.Children.map(children, (child) => {
    if (React.isValidElement(child) && (child.type === ImageSpread || child.type === ImageBleed)) {
      return React.cloneElement(child as React.ReactElement<any>, { 'dataUhuu': hasDataUhuu });
    }
    return child;
  });

  const defaultClassName = hasImageSpreadOrBleed ? "uhuu-image-block uhuu-image-block-fill" : "uhuu-image-block";

  return (
    <div className={cnPage(defaultClassName, className)} style={style}>
      <div
        {...bodyDialogProps}
        className={cnPage(
          "uhuu-image-body",
          isEmptyImage && "uhuu-image-empty",
          mergedDialogProps.className,
        )}
      >
        {renderImageContent()}
        {childrenWithProps}
        {renderOverlay(overlaySvg, overlayClassName)}
      </div>
      {renderOptionsButton(options, showOptions)}
    </div>
  )
}

export default ImageWithOptions
