import { useCallback, useContext, useEffect, useId, useMemo, useRef, useState, type CSSProperties } from 'react';
import { createPortal } from 'react-dom';
import { Pencil, SlidersHorizontal } from 'lucide-react';
import { Button } from '../../ui/button';
import { Label } from '../../ui/label';
import { Select } from '../../ui/select';
import { Switch } from '../../ui/switch';
import { cn } from '../../ui/cn';
import { useShellTranslation } from '../../i18n/locale-context';
import type { LocalizedText } from '../../i18n/i18n-core.js';
import { isRendererMode, useInteractive } from '../interactive-mode-context';
import { usePortalRoot } from '../portal-root';
import { getToolbarSlot, useToolbarSlot } from '../toolbar-slot';
import { TemplateDataContext } from './template-data-provider';
import {
  coerceDocumentOptionValue,
  documentOptionEditDialog,
  documentOptionType,
  documentOptionWriteMode,
  findDocumentOptionChoice,
  isDocumentOptionOn,
  readDocumentOption,
  type DocumentOptionDefinition,
  type DocumentOptionsHost,
} from './document-options-core.js';

export type { DocumentOptionDefinition } from './document-options-core.js';

export interface DocumentOptionsProps {
  /**
   * The document payload the template renders. Without it the control reads the surrounding
   * TemplateDataProvider's payload.
   */
  payload?: Record<string, unknown> | null;
  options: DocumentOptionDefinition[];
  /** Heading of the control; default: the shell's "Document options", in the interface language. */
  title?: LocalizedText;
  /** Called for local choices when there is no supported editor dialog on the page. */
  onChange?: (key: string, value: unknown) => void;
  /** Positions the control's own floating bar (bottom right) when no PageEditor toolbar is on screen. */
  className?: string;
  style?: CSSProperties;
}

// The select's value while the document holds no value among the options.
const UNSET = '__uhuu_document_option_unset__';

let warnedNoHost = false;

function pageHost(): DocumentOptionsHost | undefined {
  return typeof window === 'undefined' ? undefined : (window as any).$uhuu;
}

/**
 * A portal container of the control's own, for a page without InteractiveModeProvider (whose
 * container the shell's scoped styles reach). Created after mount, never on the server.
 */
function useOwnPortalContainer(enabled: boolean): HTMLElement | null {
  const [container, setContainer] = useState<HTMLElement | null>(null);
  useEffect(() => {
    if (!enabled || typeof document === 'undefined') return;
    // A PageEditor toolbar registered in this commit: the control joins it instead.
    if (getToolbarSlot()) return;
    const element = document.createElement('div');
    element.setAttribute('data-uhuu-portal', '');
    element.style.cssText = 'position: fixed; top: 0; left: 0; z-index: 9999;';
    document.body.appendChild(element);
    setContainer(element);
    return () => {
      element.remove();
      setContainer(null);
    };
  }, [enabled]);
  return enabled ? container : null;
}

/**
 * Document-level options a template draws in the editor shell: switches for top-level payload keys
 * (`payload.language`) that the platform's template theme options used to show in the editor
 * header. The released editor's `$uhuu.editDialog()` writes the same key as a user edit.
 *
 * Joins PageEditor's floating toolbar when one is on screen, else draws its own small floating bar
 * at the bottom right. Never drawn outside edit mode, in the PDF renderer or in print.
 */
export function DocumentOptions({ payload: payloadProp, options, title, onChange, className, style }: DocumentOptionsProps) {
  const { interactive } = useInteractive();
  const { t, localize } = useShellTranslation();
  const templateData = useContext(TemplateDataContext);
  const payload = payloadProp ?? templateData?.payload ?? null;
  const definitions = useMemo(() => Array.isArray(options) ? options : [], [options]);

  const visible = interactive && !isRendererMode() && definitions.length > 0;
  const toolbarSlot = useToolbarSlot();
  const portalRoot = usePortalRoot();
  // Outside InteractiveModeProvider there is no shell portal to draw the floating bar into.
  const ownContainer = useOwnPortalContainer(visible && !toolbarSlot && !portalRoot.inProvider);
  const container = toolbarSlot ?? portalRoot.portalContainer ?? ownContainer;

  const id = useId();
  const panelId = `${id}-panel`;
  const headingId = `${id}-heading`;
  const wrapperRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const [open, setOpen] = useState(false);
  const [placement, setPlacement] = useState<{ side: 'top' | 'bottom'; maxHeight?: number }>({ side: 'top' });

  // Local choices survive unrelated payload updates. A change to that option's stored value is
  // authoritative (the echo or another editor control), and clears only that key's pending choice.
  const [pending, setPending] = useState<Record<string, { value: unknown; previousValue: unknown }>>({});
  useEffect(() => {
    setPending((previous) => {
      const remaining = Object.fromEntries(Object.entries(previous).filter(([key, entry]) => {
        const definition = definitions.find((option) => option.key === key);
        return definition && Object.is(readDocumentOption(payload, definition), entry.previousValue);
      }));
      return Object.keys(remaining).length === Object.keys(previous).length ? previous : remaining;
    });
  }, [payload, definitions]);

  const valueOf = (definition: DocumentOptionDefinition) => {
    const stored = readDocumentOption(payload, definition);
    const entry = pending[definition.key];
    return entry && Object.is(stored, entry.previousValue) ? entry.value : stored;
  };

  const closePanel = useCallback((restoreFocus: boolean) => {
    setOpen(false);
    if (restoreFocus) triggerRef.current?.focus();
  }, []);

  const openPanel = () => {
    const rect = triggerRef.current?.getBoundingClientRect();
    if (rect && typeof window !== 'undefined') {
      // Open towards the larger part of the viewport: up from the bottom-right toolbar.
      const side = rect.top + rect.height / 2 > window.innerHeight / 2 ? 'top' : 'bottom';
      const room = side === 'top' ? rect.top : window.innerHeight - rect.bottom;
      setPlacement({ side, maxHeight: Math.max(160, Math.floor(room - 24)) });
    }
    setOpen(true);
  };

  // Hidden (export mode, DEV print modes) closes the panel: it reopens from the trigger.
  useEffect(() => {
    if (!visible) setOpen(false);
  }, [visible]);

  useEffect(() => {
    if (!open) return;
    panelRef.current?.querySelector<HTMLElement>('select, button')?.focus();
    const closeOnOutsidePointer = (event: PointerEvent) => {
      if (!wrapperRef.current?.contains(event.target as Node)) setOpen(false);
    };
    document.addEventListener('pointerdown', closeOnOutsidePointer, true);
    return () => document.removeEventListener('pointerdown', closeOnOutsidePointer, true);
  }, [open]);

  const openEditorDialog = (definition: DocumentOptionDefinition) => {
    const uhuu = pageHost();
    if (typeof uhuu?.editDialog !== 'function') return;
    uhuu.editDialog(documentOptionEditDialog(definition, readDocumentOption(payload, definition), localize));
    setOpen(false);
  };

  const write = (definition: DocumentOptionDefinition, choice: unknown) => {
    const uhuu = pageHost();
    const mode = documentOptionWriteMode(uhuu);
    if (mode === 'dialog') {
      openEditorDialog(definition);
      return;
    }
    const value = coerceDocumentOptionValue(definition, choice);
    if (!warnedNoHost) {
      warnedNoHost = true;
      console.warn('[uhuu-components] DocumentOptions: no supported $uhuu.editDialog on this page; a change only calls onChange.');
    }
    setPending((previous) => ({
      ...previous,
      [definition.key]: { value, previousValue: readDocumentOption(payload, definition) },
    }));
    onChange?.(definition.key, value);
  };

  if (!visible || !container || typeof document === 'undefined') return null;

  const resolvedTitle = localize(title) ?? t('documentOptions.title');
  // Read on every render: the SDK is a script the page loads before the template.
  const dialogFallback = documentOptionWriteMode(pageHost()) === 'dialog';

  const describe = (definition: DocumentOptionDefinition, descriptionId: string) => {
    const description = localize(definition.description);
    return description
      ? <p id={descriptionId} className="uhuu:text-xs uhuu:text-gray-500">{description}</p>
      : null;
  };

  const renderOption = (definition: DocumentOptionDefinition, index: number) => {
    const controlId = `${id}-option-${index}`;
    const descriptionId = `${controlId}-description`;
    const describedBy = definition.description ? descriptionId : undefined;
    const label = localize(definition.label) ?? definition.key;
    const value = valueOf(definition);
    const toggle = documentOptionType(definition) === 'toggle';
    const choices = Array.isArray(definition.options) ? definition.options : [];
    const choice = toggle ? undefined : findDocumentOptionChoice(definition, value);
    const unsetLabel = value === undefined || value === null || value === '' ? t('documentOptions.notSet') : String(value);

    if (dialogFallback) {
      const valueLabel = toggle
        ? t(isDocumentOptionOn(value) ? 'documentOptions.on' : 'documentOptions.off')
        : choice ? (localize(choice.label) ?? String(choice.value)) : unsetLabel;
      return (
        <div key={definition.key} className="uhuu:space-y-1.5">
          <button
            type="button"
            aria-haspopup="dialog"
            aria-describedby={describedBy}
            title={t('documentOptions.change', { name: label })}
            onClick={() => openEditorDialog(definition)}
            className="uhuu:flex uhuu:w-full uhuu:items-center uhuu:justify-between uhuu:gap-3 uhuu:rounded-md uhuu:border uhuu:border-gray-200 uhuu:bg-(--uhuu-shell-surface) uhuu:px-2.5 uhuu:py-1.5 uhuu:text-left uhuu:transition-colors uhuu:hover:bg-gray-50 uhuu:focus-visible:outline-none uhuu:focus-visible:ring-2 uhuu:focus-visible:ring-gray-200"
          >
            <span className="uhuu:min-w-0">
              <span className="uhuu:block uhuu:text-xs uhuu:font-medium uhuu:text-gray-500">{label}</span>
              <span className="uhuu:block uhuu:truncate uhuu:text-sm uhuu:text-gray-900">{valueLabel}</span>
            </span>
            <Pencil aria-hidden="true" className="uhuu:h-3.5 uhuu:w-3.5 uhuu:shrink-0 uhuu:text-gray-400" />
          </button>
          {describe(definition, descriptionId)}
        </div>
      );
    }

    if (toggle) {
      return (
        <div key={definition.key} className="uhuu:space-y-1">
          <div className="uhuu:flex uhuu:items-center uhuu:justify-between uhuu:gap-3 uhuu:py-1">
            <Label htmlFor={controlId} className="uhuu:text-xs uhuu:font-medium uhuu:text-gray-500">{label}</Label>
            <Switch
              id={controlId}
              aria-describedby={describedBy}
              checked={isDocumentOptionOn(value)}
              onCheckedChange={(checked) => write(definition, checked)}
            />
          </div>
          {describe(definition, descriptionId)}
        </div>
      );
    }

    return (
      <div key={definition.key} className="uhuu:space-y-1.5">
        <Label htmlFor={controlId} className="uhuu:text-xs uhuu:font-medium uhuu:text-gray-500">{label}</Label>
        <Select
          id={controlId}
          aria-describedby={describedBy}
          value={choice ? String(choice.value) : UNSET}
          onChange={(event) => {
            const picked = choices.find((option) => String(option.value) === event.target.value);
            if (picked) write(definition, picked.value);
          }}
          className="uhuu:w-full uhuu:text-sm"
        >
          {!choice && <option value={UNSET} disabled>{unsetLabel}</option>}
          {choices.map((option, optionIndex) => (
            <option key={`${optionIndex}:${String(option.value)}`} value={String(option.value)}>
              {localize(option.label) ?? String(option.value)}
            </option>
          ))}
        </Select>
        {describe(definition, descriptionId)}
      </div>
    );
  };

  const entry = (
    <div
      ref={wrapperRef}
      className={cn('uhuu-screen-only uhuu:relative uhuu:flex uhuu:items-center', toolbarSlot && className)}
      style={toolbarSlot ? style : undefined}
      onKeyDown={(event) => {
        if (event.key !== 'Escape' || !open) return;
        event.preventDefault();
        event.stopPropagation();
        closePanel(true);
      }}
      onBlur={(event) => {
        const next = event.relatedTarget as Node | null;
        if (open && next && !wrapperRef.current?.contains(next)) setOpen(false);
      }}
    >
      <Button
        ref={triggerRef}
        type="button"
        variant="ghost"
        size="sm"
        aria-haspopup="dialog"
        aria-expanded={open}
        aria-controls={open ? panelId : undefined}
        onClick={() => (open ? closePanel(false) : openPanel())}
        className="uhuu:text-xs uhuu:font-medium uhuu:text-gray-700 uhuu:hover:bg-gray-100/80 uhuu:h-7 uhuu:px-2.5 uhuu:gap-1.5"
      >
        <SlidersHorizontal aria-hidden="true" className="uhuu:w-3.5 uhuu:h-3.5" />
        {resolvedTitle}
      </Button>
      {open && (
        <div
          ref={panelRef}
          id={panelId}
          role="dialog"
          aria-labelledby={headingId}
          className={cn(
            'uhuu:absolute uhuu:right-0 uhuu:z-50 uhuu:w-72 uhuu:max-w-[calc(100vw-2rem)] uhuu:overflow-y-auto uhuu:rounded-md uhuu:border uhuu:border-gray-200 uhuu:bg-(--uhuu-shell-surface) uhuu:p-3 uhuu:text-gray-900 uhuu:shadow-md',
            placement.side === 'top' ? 'uhuu:bottom-full uhuu:mb-3' : 'uhuu:top-full uhuu:mt-3',
          )}
          style={{ maxHeight: placement.maxHeight }}
        >
          <h2 id={headingId} className="uhuu:mb-3 uhuu:text-sm uhuu:font-medium uhuu:text-gray-900">{resolvedTitle}</h2>
          <div className="uhuu:space-y-3">{definitions.map(renderOption)}</div>
        </div>
      )}
    </div>
  );

  if (toolbarSlot) return createPortal(entry, toolbarSlot);

  return createPortal(
    <div
      data-uhuu-editor
      className={cn(
        'uhuu-screen-only uhuu:fixed uhuu:right-4 uhuu:bottom-4 uhuu:z-50 uhuu:flex uhuu:items-center uhuu:p-1.5 uhuu:bg-(--uhuu-shell-surface)/90 uhuu:backdrop-blur-md uhuu:border uhuu:border-gray-200/60 uhuu:rounded-lg uhuu:shadow-sm',
        className,
      )}
      style={style}
    >
      {entry}
    </div>,
    container,
  );
}
