// src/uhuu/editor-shell/document/document-options-core.js
// Pure, DOM-free core of EditorShell.DocumentOptions: which value a document option shows, how a
// choice is typed before it is written, and how it reaches the uhuu document editor. The React
// control is document-options.tsx; docs/document-options.md describes the contract.
//
// A document option is a top-level payload key the template reads (`payload.language`), the same
// key and values the platform's template theme options wrote, so documents need no migration.

/** `select` (the default) or `toggle`. */
export function documentOptionType(definition) {
  return definition?.type === 'toggle' ? 'toggle' : 'select';
}

/** The type a choice is written as: the declared one, else `boolean` for a toggle, `string` otherwise. */
export function documentOptionValueType(definition) {
  const declared = definition?.valueType;
  if (declared === 'string' || declared === 'number' || declared === 'boolean') return declared;
  return documentOptionType(definition) === 'toggle' ? 'boolean' : 'string';
}

function isRecord(value) {
  return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** The value the document holds for the option: `payload[key]`, else the definition's default. */
export function readDocumentOption(payload, definition) {
  const stored = isRecord(payload) && definition?.key ? payload[definition.key] : undefined;
  return stored ?? definition?.defaultValue;
}

/**
 * Whether two option values are the same choice. Compared as strings: the platform's dropdown
 * always stored the option's string, while templates often default to a number (`2` is `"2"`).
 */
export function sameDocumentOptionValue(a, b) {
  if (a === undefined || a === null || b === undefined || b === null) return false;
  return String(a) === String(b);
}

/** The select option a value matches, if any. */
export function findDocumentOptionChoice(definition, value) {
  const choices = Array.isArray(definition?.options) ? definition.options : [];
  return choices.find((choice) => sameDocumentOptionValue(choice?.value, value));
}

/** A toggle is on for `true` and `"true"`, the two forms a boolean takes in saved payloads. */
export function isDocumentOptionOn(value) {
  return value === true || value === 'true';
}

/** "" and whitespace are not numbers, although Number("") is 0. */
function asNumber(value) {
  if (typeof value === 'number') return Number.isFinite(value) ? value : undefined;
  if (typeof value !== 'string' || value.trim() === '') return undefined;
  const number = Number(value);
  return Number.isFinite(number) ? number : undefined;
}

/**
 * A choice typed as the option declares, ready to write: `number` converts (a value that is not a
 * number is kept as it is), `boolean` takes `true` / `"true"`, `string` stringifies.
 */
export function coerceDocumentOptionValue(definition, value) {
  if (value === undefined || value === null) return value;
  switch (documentOptionValueType(definition)) {
    case 'number': {
      const number = asNumber(value);
      return number === undefined ? value : number;
    }
    case 'boolean':
      return isDocumentOptionOn(value);
    default:
      return String(value);
  }
}

/**
 * Use the released editor's field dialog. `$uhuu.editor.post` is only a generic transport:
 * its presence does not establish that the host handles a `patchPayload` message. Keep direct
 * writes disabled until the editor publishes a supported capability contract.
 */
export function documentOptionWriteMode(uhuu) {
  if (typeof uhuu?.editDialog === 'function') return 'dialog';
  return 'none';
}

/**
 * The `$uhuu.editDialog()` request for an option, supported by released editors: the editor's
 * select or switch field for the top-level key. That field renders plain strings, so labels are
 * resolved (`localize`) and select values stringified; it saves strings for a select, as the
 * platform's dropdown did. `value` is shown when the document does not hold the key yet.
 */
export function documentOptionEditDialog(definition, currentValue, localize = (text) => (typeof text === 'string' ? text : undefined)) {
  const label = localize(definition.label) ?? definition.key;
  if (documentOptionType(definition) === 'toggle') {
    return { path: definition.key, type: 'switch', label, value: isDocumentOptionOn(currentValue) };
  }
  const choices = Array.isArray(definition.options) ? definition.options : [];
  return {
    path: definition.key,
    type: 'select',
    label,
    ...(currentValue === undefined || currentValue === null ? {} : { value: String(currentValue) }),
    options: choices.map((choice) => ({
      value: String(choice.value),
      label: localize(choice.label) ?? String(choice.value),
    })),
  };
}
