// src/uhuu/appearance/appearance-core.js
// Pure, DOM-free core of the editor shell's appearance (light or dark chrome). The DOM and React
// wiring is in appearance-runtime.ts, the colours in styles/uhuu-appearance.css. Only the shell's
// chrome follows the appearance; pages are paper and never change.
//
// The shell is a receiver, like the uhuu SPAs (uhuu-embed docs/appearance.md): the host says which
// appearance to use. Templates run in third-party frames, so the shell never reads a cookie or the
// operating system's preference.

export const DEFAULT_APPEARANCE = 'light';

/** The values the shell draws. `system` is not one: the host resolves it before handing it on. */
export const APPEARANCES = ['light', 'dark'];

/** `?appearance=dark` on the template URL: the first-paint hint the uhuu document editor appends. */
export const APPEARANCE_QUERY_PARAM = 'appearance';

/** Attribute on `<html>` the shell's stylesheet keys its dark chrome on. */
export const APPEARANCE_ATTRIBUTE = 'data-uhuu-appearance';

/** Editor → template message that changes the appearance while the document is open. */
export const APPEARANCE_MESSAGE_ACTION = 'appearance';

/** Editor → template handshake answer; its `data.appearance` is the appearance at load. */
export const HANDSHAKE_MESSAGE_ACTION = 'shaked';

/** `light` / `dark` (any case, trimmed) → itself; anything else, `system` included → null. */
export function normalizeAppearance(value) {
  if (typeof value !== 'string') return null;
  const appearance = value.trim().toLowerCase();
  return APPEARANCES.includes(appearance) ? appearance : null;
}

/** The appearance `?appearance=` names on a location search string, if any. */
export function appearanceFromSearch(search) {
  if (typeof search !== 'string' || !search) return null;
  try {
    return normalizeAppearance(new URLSearchParams(search).get(APPEARANCE_QUERY_PARAM));
  } catch {
    return null;
  }
}

/**
 * The appearance a host message carries, if any. Host messages are JSON strings (the editor's
 * IframeMessenger) and may be objects from other hosts:
 * - `{ action: 'shaked', data: { …, appearance } }`, the handshake answer;
 * - `{ action: 'appearance', data: { appearance } }`, a change while the document is open.
 */
export function appearanceFromHostMessage(message) {
  let parsed = message;
  if (typeof message === 'string') {
    const trimmed = message.trim();
    if (!trimmed.startsWith('{')) return null;
    try {
      parsed = JSON.parse(trimmed);
    } catch {
      return null;
    }
  }
  if (!parsed || typeof parsed !== 'object') return null;
  if (parsed.action === HANDSHAKE_MESSAGE_ACTION || parsed.action === APPEARANCE_MESSAGE_ACTION) {
    return normalizeAppearance(parsed.data?.appearance);
  }
  return null;
}

/**
 * The appearance the shell draws, from the first source that names one: the template's explicit
 * choice, the host (handshake or a later change, the latest wins), `?appearance=` on the page URL,
 * then light. The renderer (PDF/print output) is always light.
 */
export function resolveAppearance(sources) {
  if (sources?.renderer) return DEFAULT_APPEARANCE;
  return (
    normalizeAppearance(sources?.explicit) ??
    normalizeAppearance(sources?.host) ??
    appearanceFromSearch(sources?.search) ??
    DEFAULT_APPEARANCE
  );
}

/**
 * Subscribes to the appearance the host announces through the uhuu SDK: `loaded` (the SDK's
 * re-emit of the handshake data) and `appearance` (SDK 1.2.3+ re-emits the change message).
 * Returns the unsubscribe. No-op without the SDK.
 */
export function subscribeHostAppearance(uhuu, onAppearance) {
  if (typeof uhuu?.listen !== 'function') return () => {};
  const offs = ['loaded', APPEARANCE_MESSAGE_ACTION].map((event) =>
    uhuu.listen(event, (data) => {
      const appearance = normalizeAppearance(data?.appearance);
      if (appearance) onAppearance(appearance);
    }),
  );
  return () => offs.forEach((off) => typeof off === 'function' && off());
}
